insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('giants-causeway', 'Giant''s Causeway', 'Antrim', 'NI', 'Bushmills', 'http://www.giantscausewayofficialguide.com/Home.aspx', 'Tens of thousands of interlocking basalt columns drop into the sea on the north Antrim coast. The stones are the draw; the official visitor building is optional.', 55.240833, -6.511667, ST_SetSRID(ST_MakePoint(-6.511667, 55.240833), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('carrick-a-rede', 'Carrick-a-Rede Rope Bridge', 'Antrim', 'NI', 'Ballintoy', 'https://www.nationaltrust.org.uk/carrick-a-rede/features/access-at-carrick-a-rede-and-larrybane', 'A short rope bridge links the mainland to a tiny basalt stack that salmon fishermen used for generations. Cross only when the National Trust has it open to weather.', 55.239559, -6.33251, ST_SetSRID(ST_MakePoint(-6.33251, 55.239559), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('dunluce-castle', 'Dunluce Castle', 'Antrim', 'NI', 'Bushmills', 'https://discovernorthernireland.com/things-to-do/dunluce-castle-medieval-irish-castle-on-the-antrim-coast-p675011', 'A ruined castle sits on a basalt outcrop above the Atlantic, half a mile of cliff path from the Causeway coast road. The kitchens once fell into the sea; the walls that remain are still worth the ticket.', 55.211389, -6.579167, ST_SetSRID(ST_MakePoint(-6.579167, 55.211389), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('navan-fort', 'Navan Fort', 'Armagh', 'NI', 'Armagh', 'https://www.armagh.co.uk/navan-centre-fort', 'A great earthen enclosure west of Armagh city, remembered as Emain Macha, the legendary capital of Ulster. The mound is quiet now; the visitor centre sits below the hill.', 54.345278, -6.718611, ST_SetSRID(ST_MakePoint(-6.718611, 54.345278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('slieve-donard', 'Slieve Donard', 'Down', 'NI', 'Newcastle', 'https://www.walkni.com/walks/slieve-donard/', 'The highest of the Mourne Mountains rises straight from Newcastle strand. The granite cone is a hard walk in any weather; the view takes in both coasts on a clear day.', 54.180278, -5.920833, ST_SetSRID(ST_MakePoint(-5.920833, 54.180278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('marble-arch-caves', 'Marble Arch Caves', 'Fermanagh', 'NI', 'Florencecourt', 'https://marblearchcaves.co.uk/', 'A river cave under Cuilcagh mountain, shown as a boat-and-walk tour through limestone chambers. Tours stop when the Cladagh is in spate; book ahead in summer.', 54.258428, -7.814314, ST_SetSRID(ST_MakePoint(-7.814314, 54.258428), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('beaghmore', 'Beaghmore Stone Circles', 'Tyrone', 'NI', 'Cookstown', 'https://discovernorthernireland.com/things-to-do/beaghmore-stone-circles-p675511', 'Seven stone circles, cairns and stone rows sit in bog country in the Sperrins, uncovered when peat was cut. It is an open site: no ticket hut, just a lane and the stones.', 54.701466, -6.938701, ST_SetSRID(ST_MakePoint(-6.938701, 54.701466), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('cliffs-of-moher', 'Cliffs of Moher', 'Clare', 'IE', 'Liscannor', 'http://www.cliffsofmoher.ie', 'Eight kilometres of Atlantic cliff, with the official visitor building at O''Brien''s Tower. The cliff path continues toward Doolin and Hag''s Head if you want the edge without the exhibition.', 52.936111, -9.470833, ST_SetSRID(ST_MakePoint(-9.470833, 52.936111), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('poulnabrone-dolmen', 'Poulnabrone dolmen', 'Clare', 'IE', 'Carran', 'https://heritageireland.ie/places-to-visit/poulnabrone-tomb/', 'A portal tomb on the Burren pavement, a capstone on two uprights that has stood since the Neolithic. There is a small car park on the R480; the limestone underfoot is sharp.', 53.04869, -9.140021, ST_SetSRID(ST_MakePoint(-9.140021, 53.04869), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('skellig-michael', 'Skellig Michael', 'Kerry', 'IE', 'Portmagee', 'https://heritageireland.ie/places-to-visit/skellig-michael/', 'A pyramid of rock eight miles off the Kerry coast, with a sixth-century monastery on the summit. Landing is by small boat from Portmagee or Ballinskelligs and is often cancelled.', 51.771111, -10.540556, ST_SetSRID(ST_MakePoint(-10.540556, 51.771111), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('carrauntoohil', 'Carrauntoohil', 'Kerry', 'IE', 'Killarney', 'https://www.killarneynationalpark.ie', 'Ireland''s highest mountain sits in the Reeks above the Gap of Dunloe. The Devil''s Ladder is the usual line and is steep loose stone; treat it as a proper mountain day.', 51.998889, -9.742778, ST_SetSRID(ST_MakePoint(-9.742778, 51.998889), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('newgrange', 'Newgrange', 'Meath', 'IE', 'Donore', 'https://newgrange.com', 'A passage tomb older than the pyramids, aligned to the winter solstice sunrise. You reach it only on a shuttle from the Brú na Bóinne visitor centre across the Boyne.', 53.694725, -6.475566, ST_SetSRID(ST_MakePoint(-6.475566, 53.694725), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('hill-of-tara', 'Hill of Tara', 'Meath', 'IE', 'Navan', 'https://heritageireland.ie/places-to-visit/hill-of-tara/', 'A low ridge of earthworks that was the ceremonial centre of early Irish kingship. The Lia Fáil standing stone and the mounds are free to walk; the old church holds a small exhibition.', 53.5775, -6.611944, ST_SetSRID(ST_MakePoint(-6.611944, 53.5775), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('rock-of-cashel', 'Rock of Cashel', 'Tipperary', 'IE', 'Cashel', 'http://www.heritageireland.ie/en/south-east/rockofcashel/', 'A cluster of medieval church buildings on a limestone crag above Cashel town — round tower, cathedral, Cormac''s Chapel with its frescoes. The rock is visible from the N8.', 52.52, -7.89, ST_SetSRID(ST_MakePoint(-7.89, 52.52), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('blarney-castle', 'Blarney Castle', 'Cork', 'IE', 'Blarney', 'http://www.blarneycastle.ie/', 'A medieval keep in woodland northwest of Cork city, famous for the stone in the battlements. The gardens and the poison garden are as much the visit as the kiss.', 51.928889, -8.570833, ST_SetSRID(ST_MakePoint(-8.570833, 51.928889), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('mizen-head', 'Mizen Head', 'Cork', 'IE', 'Goleen', 'https://www.mizenhead.ie', 'The signal station on Ireland''s south-west extremity, reached by a footbridge over a sea gorge. Weather and swell are the point; the museum is in the old lightkeepers'' houses.', 51.450278, -9.819444, ST_SetSRID(ST_MakePoint(-9.819444, 51.450278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('dun-aonghasa', 'Dún Aonghasa', 'Galway', 'IE', 'Kilronan', 'https://heritageireland.ie/places-to-visit/dun-aonghasa/', 'A semicircular stone fort on the edge of a 90-metre cliff on Inis Mór. There is no barrier at the drop. Boats run from Rossaveel and, in season, from Doolin.', 53.12591, -9.76636, ST_SetSRID(ST_MakePoint(-9.76636, 53.12591), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('kylemore-abbey', 'Kylemore Abbey', 'Galway', 'IE', 'Letterfrack', 'https://www.kylemoreabbey.com', 'A Victorian castle on a Connemara lake, later a Benedictine abbey, with a restored walled garden in the next valley. The N59 runs the shore below the façade.', 53.56168, -9.889265, ST_SetSRID(ST_MakePoint(-9.889265, 53.56168), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('croagh-patrick', 'Croagh Patrick', 'Mayo', 'IE', 'Murrisk', 'https://www.croagh-patrick.com', 'The cone above Clew Bay that pilgrims climb, many of them barefoot, on the last Sunday in July. The path from Murrisk is steep quartzite; the oratory is on the summit.', 53.7595, -9.6584, ST_SetSRID(ST_MakePoint(-9.6584, 53.7595), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('slieve-league', 'Slieve League', 'Donegal', 'IE', 'Teelin', 'https://www.slieveleaguecliffs.ie', 'Sea cliffs that rise almost 600 metres from Donegal Bay. A road reaches a viewing point; One Man''s Pass along the ridge is a serious walk in wind.', 54.638056, -8.681389, ST_SetSRID(ST_MakePoint(-8.681389, 54.638056), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('glendalough', 'Glendalough', 'Wicklow', 'IE', 'Laragh', 'https://heritageireland.ie/places-to-visit/glendalough-visitor-centre/', 'A monastic settlement in a two-lake glacial valley — round tower, stone churches, and the Miners'' Road around the upper lake. The visitor centre is at the valley mouth.', 53.010278, -6.3275, ST_SetSRID(ST_MakePoint(-6.3275, 53.010278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('kilkenny-castle', 'Kilkenny Castle', 'Kilkenny', 'IE', 'Kilkenny', 'https://www.kilkennycastle.ie', 'A restored castle on the River Nore in the middle of Kilkenny, with parkland behind it. The parade and the design centre sit across the street.', 52.650278, -7.249167, ST_SetSRID(ST_MakePoint(-7.249167, 52.650278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('clonmacnoise', 'Clonmacnoise', 'Offaly', 'IE', 'Shannonbridge', 'https://heritageireland.ie/places-to-visit/clonmacnoise/', 'An early monastery on a bend of the Shannon, with high crosses, a round tower and a graveyard of kings. The river is the reason it was here.', 53.323889, -7.991111, ST_SetSRID(ST_MakePoint(-7.991111, 53.323889), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('rock-of-dunamase', 'Rock of Dunamase', 'Laois', 'IE', 'Portlaoise', 'https://heritageireland.ie/places-to-visit/rock-of-dunamase/', 'A ruined castle on a limestone outcrop east of Portlaoise, looking over the Heath. There is no ticket office; a short path from the car park reaches the gatehouse.', 53.031667, -7.210278, ST_SetSRID(ST_MakePoint(-7.210278, 53.031667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('castletown-house', 'Castletown House', 'Kildare', 'IE', 'Celbridge', 'https://castletown.ie/', 'Ireland''s first great Palladian house, set in parkland at Celbridge. The long axial avenue and the interiors are the visit; the café sits in the west wing.', 53.34, -6.538611, ST_SetSRID(ST_MakePoint(-6.538611, 53.34), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('brownshill-dolmen', 'Brownshill Dolmen', 'Carlow', 'IE', 'Carlow', 'https://heritageireland.ie/places-to-visit/brownshill-dolmen/', 'A portal tomb in a field east of Carlow town whose capstone is among the heaviest in Europe. A short fenced path from the road; no staff on site.', 52.8375, -6.881111, ST_SetSRID(ST_MakePoint(-6.881111, 52.8375), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('monasterboice', 'Monasterboice', 'Louth', 'IE', 'Drogheda', 'https://heritageireland.ie/places-to-visit/monasterboice/', 'A round tower and two high crosses in a graveyard north of Drogheda. Muiredach''s Cross is the reason to stop; the site is open and unstaffed.', 53.751387, -6.434503, ST_SetSRID(ST_MakePoint(-6.434503, 53.751387), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('hill-of-uisneach', 'Hill of Uisneach', 'Westmeath', 'IE', 'Mullingar', 'https://uisneach.ie', 'A low hill in the midlands treated as the ceremonial centre of Ireland, with the Catstone erratic on its shoulder. Access is usually by guided walk on the farm.', 53.49, -7.562, ST_SetSRID(ST_MakePoint(-7.562, 53.49), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('corlea-trackway', 'Corlea Trackway', 'Longford', 'IE', 'Kenagh', 'https://heritageireland.ie/places-to-visit/corlea-trackway/', 'An Iron Age oak road, eight metres wide, preserved in a Longford bog and shown inside an OPW hall built over the timbers. The surrounding bog is still wet.', 53.62675, -7.853444, ST_SetSRID(ST_MakePoint(-7.853444, 53.62675), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('rathcroghan', 'Rathcroghan', 'Roscommon', 'IE', 'Tulsk', 'https://www.rathcroghan.ie', 'A landscape of earthworks around Tulsk that early sources treat as Cruachan, the royal site of Connacht. The visitor centre in the village orients you before the fields.', 53.802, -8.304, ST_SetSRID(ST_MakePoint(-8.304, 53.802), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('king-johns-castle', 'King John''s Castle', 'Limerick', 'IE', 'Limerick', 'https://www.kingjohnscastle.com', 'An Angevin castle on an island in the Shannon, with a modern exhibition inside the walls. King John''s Bridge and the Treaty Stone sit on the same stretch of river.', 52.669722, -8.625556, ST_SetSRID(ST_MakePoint(-8.625556, 52.669722), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('hook-lighthouse', 'Hook Lighthouse', 'Wexford', 'IE', 'Hook Head', 'https://hooklighthouse.ie', 'A massive medieval lighthouse still in use on the Hook peninsula. Tours climb the tower; the headland around it is all wind and birds.', 52.123806, -6.929306, ST_SetSRID(ST_MakePoint(-6.929306, 52.123806), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('glencar-waterfall', 'Glencar Waterfall', 'Leitrim', 'IE', 'Glencar', 'https://www.leitrim.ie', 'A named waterfall dropping into Glencar Lough on the Sligo–Leitrim border, a short walk from the car park. Yeats used the lake in print; the path is easy.', 54.34051, -8.36773, ST_SetSRID(ST_MakePoint(-8.36773, 54.34051), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('benbulbin', 'Benbulbin', 'Sligo', 'IE', 'Drumcliff', 'https://www.sligo.ie', 'A flat-topped limestone mountain that defines the Sligo skyline. Walks start from Gortarowey forest; the plateau edge is a cornice in winter.', 54.366667, -8.466667, ST_SetSRID(ST_MakePoint(-8.466667, 54.366667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('dublin-castle', 'Dublin Castle', 'Dublin', 'IE', 'Dublin', 'http://dublincastle.ie/', 'The castle that was the seat of British administration, now state apartments, a medieval tower and a garden on the site of the black pool that named the city.', 53.343109, -6.267394, ST_SetSRID(ST_MakePoint(-6.267394, 53.343109), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('reginalds-tower', 'Reginald''s Tower', 'Waterford', 'IE', 'Waterford', 'https://www.waterfordtreasures.com/reginalds-tower', 'A round stone tower on Waterford''s quays, the oldest civic building in Ireland still in use, holding Viking and medieval finds from the city.', 52.260489, -7.105394, ST_SetSRID(ST_MakePoint(-7.105394, 52.260489), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('cavan-burren-park', 'Cavan Burren Park', 'Cavan', 'IE', 'Blacklion', 'https://www.cavanburren.ie', 'A limestone upland on the Cavan–Fermanagh border, with megalithic tombs and a forest loop above Blacklion. The Cavan Burren is quieter than Clare''s.', 54.264734, -7.888553, ST_SetSRID(ST_MakePoint(-7.888553, 54.264734), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('clones-round-tower', 'Clones Round Tower', 'Monaghan', 'IE', 'Clones', 'https://heritageireland.ie', 'A truncated round tower and a high cross in the middle of Clones, remnants of an early monastery. The sarcophagus in the graveyard is carved in the shape of a house.', 54.177676, -7.232973, ST_SetSRID(ST_MakePoint(-7.232973, 54.177676), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('howth-head', 'Howth Head', 'Dublin', 'IE', 'Howth', 'https://www.howthhead.com', 'A peninsula east of Dublin with a cliff path, a lighthouse and views back to the city. The DART terminates at the harbour; the summit path starts above the village.', 53.37923, -6.07201, ST_SetSRID(ST_MakePoint(-6.07201, 53.37923), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('phoenix-park', 'Phoenix Park', 'Dublin', 'IE', 'Dublin', 'https://phoenixpark.ie/', 'A walled park west of the centre, large enough for a herd of fallow deer, the Zoo, and the President''s house. The Wellington Monument marks the main avenue.', 53.355789, -6.329792, ST_SetSRID(ST_MakePoint(-6.329792, 53.355789), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('trim-castle', 'Trim Castle', 'Meath', 'IE', 'Trim', 'http://www.meath.ie/Tourism/Heritage/HeritageSites/TrimCastle/', 'The largest Anglo-Norman keep in Ireland, a square tower in a riverside ward at Trim. Guided tours go inside the keep; the walls can be walked without one.', 53.554342, -6.789756, ST_SetSRID(ST_MakePoint(-6.789756, 53.554342), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('knowth', 'Knowth', 'Meath', 'IE', 'Donore', 'https://heritageireland.ie/places-to-visit/bru-na-boinne-knowth/', 'A great passage tomb beside Newgrange, covered in megalithic carving. Like Newgrange it is reached only by shuttle from the Brú na Bóinne visitor centre.', 53.701667, -6.491667, ST_SetSRID(ST_MakePoint(-6.491667, 53.701667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('powerscourt-waterfall', 'Powerscourt Waterfall', 'Wicklow', 'IE', 'Enniskerry', 'https://powerscourt.com/waterfall', 'Ireland''s highest waterfall, a separate ticket from the house and gardens at Enniskerry. A short valley walk; swimming is not the point and the rocks are slippy.', 53.146, -6.211, ST_SetSRID(ST_MakePoint(-6.211, 53.146), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('great-sugar-loaf', 'Great Sugar Loaf', 'Wicklow', 'IE', 'Kilmacanogue', 'https://www.wicklowmountainsnationalpark.ie', 'A quartzite cone inland of Bray, a short steep walk from a roadside car park. Dublin Bay and the Wicklow uplands both show from the summit.', 53.155, -6.15, ST_SetSRID(ST_MakePoint(-6.15, 53.155), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('ross-castle', 'Ross Castle', 'Kerry', 'IE', 'Killarney', 'https://heritageireland.ie/places-to-visit/ross-castle/', 'A tower house on Lough Leane, the starting point for boats to Innisfallen. The castle is OPW; the lake path is free.', 52.041, -9.531, ST_SetSRID(ST_MakePoint(-9.531, 52.041), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('muckross-house', 'Muckross House', 'Kerry', 'IE', 'Killarney', 'http://www.muckross-house.ie', 'A Victorian mansion in Killarney National Park, with gardens, a working farm and Muckross Abbey a short walk away. The house is ticketed; the park around it is not.', 52.017778, -9.501667, ST_SetSRID(ST_MakePoint(-9.501667, 52.017778), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('torc-waterfall', 'Torc Waterfall', 'Kerry', 'IE', 'Killarney', 'https://www.killarneynationalpark.ie', 'A cascade in oak woodland just off the N71 in Killarney National Park. The lower fall is a few minutes from the car park; the upper path continues toward Torc Mountain.', 52.0, -9.51667, ST_SetSRID(ST_MakePoint(-9.51667, 52.0), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('gap-of-dunloe', 'Gap of Dunloe', 'Kerry', 'IE', 'Beaufort', 'https://www.killarneynationalpark.ie', 'A glacial breach through the MacGillycuddy''s Reeks, a narrow road between black lakes. Jaunting cars start at Kate Kearney''s; cyclists and walkers use the same road.', 52.016667, -9.6355, ST_SetSRID(ST_MakePoint(-9.6355, 52.016667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('gallarus-oratory', 'Gallarus Oratory', 'Kerry', 'IE', 'Ballydavid', 'https://heritageireland.ie/places-to-visit/gallarus-oratory/', 'A dry-stone oratory shaped like an upturned boat, on the north side of the Dingle Peninsula. The visitor hut is optional; the oratory itself is the object.', 52.1725, -10.349444, ST_SetSRID(ST_MakePoint(-10.349444, 52.1725), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('staigue-fort', 'Staigue Fort', 'Kerry', 'IE', 'Castlecove', 'https://heritageireland.ie/places-to-visit/staigue-fort/', 'A thick-walled stone ringfort in a valley above Castlecove, with internal stairways in the wall. The last stretch is a farm lane; there is often an honesty box.', 51.805278, -10.015833, ST_SetSRID(ST_MakePoint(-10.015833, 51.805278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('garnish-island', 'Garnish Island', 'Cork', 'IE', 'Glengarriff', 'https://heritageireland.ie/places-to-visit/ilnacullin-garinish-island/', 'A garden island in Glengarriff harbour, planted in the early twentieth century on a sheltered rock. A small ferry from the village is the only way on.', 51.736389, -9.541111, ST_SetSRID(ST_MakePoint(-9.541111, 51.736389), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('gougane-barra', 'Gougane Barra', 'Cork', 'IE', 'Ballingeary', 'https://www.gouganebarra.com', 'A lake in a mountain corrie where St Finbarr is said to have settled, with a small oratory on the shore. A forest park loops the cliffs above the water.', 51.8394, -9.3148, ST_SetSRID(ST_MakePoint(-9.3148, 51.8394), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('aillwee-cave', 'Aillwee Cave', 'Clare', 'IE', 'Ballyvaughan', 'https://www.aillweecave.ie', 'A show cave in the Burren above Ballyvaughan, with a short underground walk and a birds-of-prey arena on the same hillside. The café terrace looks north to Galway Bay.', 53.089386, -9.145775, ST_SetSRID(ST_MakePoint(-9.145775, 53.089386), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('loop-head', 'Loop Head Lighthouse', 'Clare', 'IE', 'Kilbaha', 'https://www.loophead.ie', 'A lighthouse on the long finger of land that ends Clare. The Bridges of Ross and the cliff path are as much the visit as the light.', 52.560806, -9.932741, ST_SetSRID(ST_MakePoint(-9.932741, 52.560806), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('fanad-head-lighthouse', 'Fanad Head Lighthouse', 'Donegal', 'IE', 'Fanad', 'https://www.fanadlighthouse.com', 'A lighthouse on the Atlantic side of Lough Swilly, with tours of the tower and keepers'' cottages to stay in. The peninsula road is the long way round from Letterkenny.', 55.276278, -7.631722, ST_SetSRID(ST_MakePoint(-7.631722, 55.276278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('malin-head', 'Malin Head', 'Donegal', 'IE', 'Malin', 'https://www.malinhead.ie', 'Ireland''s most northerly point, a low headland of rock and a watch tower at Banba''s Crown. The weather station and the WW2 lookout sit in the same wind.', 55.380806, -7.37, ST_SetSRID(ST_MakePoint(-7.37, 55.380806), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('glenveagh-castle', 'Glenveagh Castle', 'Donegal', 'IE', 'Churchill', 'https://www.glenveaghnationalpark.ie', 'A nineteenth-century castle on Lough Veagh inside the national park, with Italianate gardens. A shuttle from the visitor centre is the usual approach; the park itself is open.', 55.033333, -7.966667, ST_SetSRID(ST_MakePoint(-7.966667, 55.033333), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('ceide-fields', 'Céide Fields', 'Mayo', 'IE', 'Ballycastle', 'https://heritageireland.ie/places-to-visit/ceide-fields/', 'A Neolithic field system preserved under blanket bog on the north Mayo coast. The OPW building is a glass pyramid on the cliff; the fields are cut as sections in the peat.', 54.307222, -9.457778, ST_SetSRID(ST_MakePoint(-9.457778, 54.307222), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('downpatrick-head', 'Downpatrick Head', 'Mayo', 'IE', 'Ballycastle', 'https://www.mayo.ie', 'A cliff headland on the north Mayo coast with a detached sea stack, Dún Briste, and a blow-hole in the grass. Stay back from the edge; the ground is undercut.', 54.326, -9.346, ST_SetSRID(ST_MakePoint(-9.346, 54.326), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('cong-abbey', 'Cong Abbey', 'Mayo', 'IE', 'Cong', 'https://heritageireland.ie/places-to-visit/cong-abbey/', 'The ruins of an Augustinian abbey in Cong, with a later cloister and a dry canal nearby that never took water. The Quiet Man is filmed folklore; the stone is the visit.', 53.541004, -9.286743, ST_SetSRID(ST_MakePoint(-9.286743, 53.541004), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('drombeg-stone-circle', 'Drombeg Stone Circle', 'Cork', 'IE', 'Glandore', 'https://heritageireland.ie/places-to-visit/drombeg-stone-circle/', 'A recumbent stone circle in west Cork, with a cooking pit beside it. The site is open from a small car park off the road between Glandore and Rosscarbery.', 51.564553, -9.08702, ST_SetSRID(ST_MakePoint(-9.08702, 51.564553), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('jerpoint-abbey', 'Jerpoint Abbey', 'Kilkenny', 'IE', 'Thomastown', 'https://heritageireland.ie/places-to-visit/jerpoint-abbey/', 'A Cistercian abbey south of Thomastown, known for the carved figures on the cloister. OPW staff the site in season; the ruin is beside the old Dublin–Waterford road.', 52.51093, -7.15798, ST_SetSRID(ST_MakePoint(-7.15798, 52.51093), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('dunmore-cave', 'Dunmore Cave', 'Kilkenny', 'IE', 'Castlecomer', 'https://heritageireland.ie/places-to-visit/dunmore-cave/', 'A cave in limestone north of Kilkenny city, shown on a guided tour, with a Viking-age massacre in the record. The chambers are short; the steps are steep.', 52.733928, -7.2469, ST_SetSRID(ST_MakePoint(-7.2469, 52.733928), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('malahide-castle', 'Malahide Castle', 'Dublin', 'IE', 'Malahide', 'http://malahidecastle.com', 'A castle in a public park at Malahide, with Talbot botanic gardens beside it. The park is free; the house is a ticket. DART to Malahide.', 53.444722, -6.165, ST_SetSRID(ST_MakePoint(-6.165, 53.444722), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('carrickfergus-castle', 'Carrickfergus Castle', 'Antrim', 'NI', 'Carrickfergus', 'http://www.carrickfergus.org/tourism/attractions/carrickfergus-castle/', 'A Norman keep on a rock in Belfast Lough, still a complete enclosure. The harbour and the town sit against the walls.', 54.7133, -5.80645, ST_SetSRID(ST_MakePoint(-5.80645, 54.7133), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('mussenden-temple', 'Mussenden Temple', 'Derry', 'NI', 'Castlerock', 'https://www.nationaltrust.org.uk/visit/northern-ireland/mussenden-temple-and-downhill-demesne', 'A clifftop rotunda on the Downhill Demesne, a library built as a temple above the railway. The National Trust holds the demesne; the cliff path is the visit.', 55.1678, -6.81084, ST_SetSRID(ST_MakePoint(-6.81084, 55.1678), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('grianan-of-aileach', 'Grianán of Aileach', 'Donegal', 'IE', 'Burt', 'https://heritageireland.ie/places-to-visit/grianan-of-aileach/', 'A restored stone ringfort on a hill above the Inishowen neck, looking at both Lough Swilly and Lough Foyle. A steep lane from Burt; the walls are high and windy.', 55.016667, -7.433333, ST_SetSRID(ST_MakePoint(-7.433333, 55.016667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('carrowmore', 'Carrowmore Megalithic Cemetery', 'Sligo', 'IE', 'Sligo', 'https://heritageireland.ie/places-to-visit/carrowmore-megalithic-cemetery/', 'A spread of passage tombs on the Cúil Irra peninsula, with Knocknarea in view. The OPW visitor building sits among the circles; several tombs are in the surrounding fields.', 54.250861, -8.519167, ST_SetSRID(ST_MakePoint(-8.519167, 54.250861), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('knocknarea', 'Knocknarea', 'Sligo', 'IE', 'Strandhill', 'https://www.sligo.ie', 'A limestone hill west of Sligo with a huge cairn on top, traditionally Queen Maeve''s. The path from Strandhill is a popular short climb; stay off the cairn itself.', 54.25891, -8.57463, ST_SetSRID(ST_MakePoint(-8.57463, 54.25891), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('parkes-castle', 'Parke''s Castle', 'Leitrim', 'IE', 'Dromahair', 'https://heritageireland.ie/places-to-visit/parkes-castle/', 'A plantation castle on the shore of Lough Gill, restored as an OPW site. Boats on the lake and the road to Dromahair share the same shore.', 54.264792, -8.33443, ST_SetSRID(ST_MakePoint(-8.33443, 54.264792), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('creeveykeel', 'Creevykeel Court Tomb', 'Sligo', 'IE', 'Cliffoney', 'https://heritageireland.ie/places-to-visit/creevykeel-court-tomb/', 'A court tomb in a field beside the N15 at Cliffoney, one of the easier megaliths to reach from a main road. A short path from a lay-by.', 54.4387, -8.4335, ST_SetSRID(ST_MakePoint(-8.4335, 54.4387), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('kilmacduagh', 'Kilmacduagh', 'Galway', 'IE', 'Gort', 'https://heritageireland.ie/places-to-visit/kilmacduagh-monastic-site/', 'A round tower that leans, and a cluster of church ruins, on the edge of the Burren near Gort. The site is open; the tower is among the tallest in Ireland.', 53.046944, -8.885, ST_SetSRID(ST_MakePoint(-8.885, 53.046944), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('dunguaire-castle', 'Dunguaire Castle', 'Galway', 'IE', 'Kinvara', 'https://www.dunguairecastle.com', 'A tower house on a spit in Galway Bay at Kinvara, a postcard of the Wild Atlantic Way. The medieval banquet is a separate product; the tower can be visited by day.', 53.142222, -8.926111, ST_SetSRID(ST_MakePoint(-8.926111, 53.142222), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('aughnanure-castle', 'Aughnanure Castle', 'Galway', 'IE', 'Oughterard', 'http://www.galway.net/galwayguide/todo/sights/county_galway/aughnanure_castle/', 'An O''Flaherty tower house in woodland near Oughterard, with a double bawn and a river beside it. OPW in season.', 53.417694, -9.271197, ST_SetSRID(ST_MakePoint(-9.271197, 53.417694), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('coole-park', 'Coole Park', 'Galway', 'IE', 'Gort', 'https://www.coolepark.ie', 'The woods and turlough that were Lady Gregory''s Coole, with the Autograph Tree still standing. The house is gone; the park is a NPWS nature reserve.', 53.096634, -8.835046, ST_SetSRID(ST_MakePoint(-8.835046, 53.096634), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('bunratty-castle', 'Bunratty Castle', 'Clare', 'IE', 'Bunratty', 'http://www.shannonheritage.com', 'A restored tower house beside the Shannon, with a folk park of relocated buildings in the grounds. The castle is the artefact; the park is a museum of rural rooms.', 52.696667, -8.811806, ST_SetSRID(ST_MakePoint(-8.811806, 52.696667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('knappogue-castle', 'Knappogue Castle', 'Clare', 'IE', 'Quin', 'https://www.knappoguecastle.ie', 'A McNamara tower house in east Clare, restored as a visitor castle near Quin Abbey. The banquet is evening-only; daytime visits cover the tower.', 52.793919, -8.831597, ST_SetSRID(ST_MakePoint(-8.831597, 52.793919), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('quin-abbey', 'Quin Abbey', 'Clare', 'IE', 'Quin', 'https://heritageireland.ie/places-to-visit/quin-friar/', 'A Franciscan friary in the village of Quin, among the better-preserved in Ireland, with cloister and tower still standing. No ticket; watch your step on the stairs.', 52.819286, -8.863019, ST_SetSRID(ST_MakePoint(-8.863019, 52.819286), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('athlone-castle', 'Athlone Castle', 'Westmeath', 'IE', 'Athlone', 'https://www.athlonecastle.ie', 'A castle on the Shannon crossing that still commands the bridge. The exhibition inside covers the siege and the river; the town is on both banks.', 53.42333, -7.9425, ST_SetSRID(ST_MakePoint(-7.9425, 53.42333), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('fore-abbey', 'Fore Abbey', 'Westmeath', 'IE', 'Fore', 'https://heritageireland.ie/places-to-visit/fore-priory/', 'A Benedictine priory in a valley of the north Westmeath lakes, tied to the local ''seven wonders''. The ruins and the anchorite''s cell are an open site.', 53.683899, -7.227175, ST_SetSRID(ST_MakePoint(-7.227175, 53.683899), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('belvedere-house', 'Belvedere House', 'Westmeath', 'IE', 'Mullingar', 'https://belvedere-house.ie', 'An eighteenth-century house on Lough Ennell with gardens and the Jealous Wall folly. The park is the walk; the house is a smaller interior.', 53.477, -7.368, ST_SetSRID(ST_MakePoint(-7.368, 53.477), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('emo-court', 'Emo Court', 'Laois', 'IE', 'Emo', 'https://heritageireland.ie/places-to-visit/emo-court/', 'A James Gandon house in parkland in Laois, with a long lake. OPW restored the interiors; the park is open more of the year than the rooms.', 53.107178, -7.197064, ST_SetSRID(ST_MakePoint(-7.197064, 53.107178), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('portumna-castle', 'Portumna Castle', 'Galway', 'IE', 'Portumna', 'https://heritageireland.ie/places-to-visit/portumna-castle/', 'A semi-fortified house at the head of Lough Derg, restored by OPW. Portumna Forest Park next door is the longer walk, with deer and lake shore.', 53.086677, -8.220729, ST_SetSRID(ST_MakePoint(-8.220729, 53.086677), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('cahir-castle', 'Cahir Castle', 'Tipperary', 'IE', 'Cahir', 'http://www.heritageireland.ie/en/south-east/cahircastle/', 'A well-preserved castle on a rock in the River Suir in the middle of Cahir. OPW tours the interiors; the Swiss Cottage is a separate site upriver.', 52.37455, -7.92719, ST_SetSRID(ST_MakePoint(-7.92719, 52.37455), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('ardmore-round-tower', 'Ardmore Round Tower', 'Waterford', 'IE', 'Ardmore', 'https://heritageireland.ie/places-to-visit/ardmore-cathedral/', 'A round tower and ruined cathedral on the cliff above Ardmore, with Ogham stones and a cliff walk around the headland. St Declan''s well sits on the path.', 51.94857, -7.72611, ST_SetSRID(ST_MakePoint(-7.72611, 51.94857), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('kells-priory', 'Kells Priory', 'Kilkenny', 'IE', 'Kells', 'https://heritageireland.ie/places-to-visit/kells-priory/', 'An Augustinian priory in a walled precinct beside the King''s River at Kells, Co. Kilkenny. The enclosure is large and unstaffed; the village is not the Meath Kells.', 52.538333, -7.266944, ST_SetSRID(ST_MakePoint(-7.266944, 52.538333), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('moone-high-cross', 'Moone High Cross', 'Kildare', 'IE', 'Moone', 'https://heritageireland.ie/places-to-visit/moone-high-cross/', 'A tall, slender granite high cross in the ruins of a monastery at Moone. A glass roof now covers the cross; the site is a short pull-off from the N9.', 52.979465, -6.825247, ST_SetSRID(ST_MakePoint(-6.825247, 52.979465), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('lough-gur', 'Lough Gur', 'Limerick', 'IE', 'Bruff', 'https://loughgur.com', 'A lake in east Limerick ringed with prehistoric sites, including the Grange stone circle. The visitor centre sits on the shore; several monuments are a short walk.', 52.516381, -8.533278, ST_SetSRID(ST_MakePoint(-8.533278, 52.516381), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('kilmainham-gaol', 'Kilmainham Gaol', 'Dublin', 'IE', 'Dublin', 'https://kilmainhamgaolmuseum.ie/', 'The prison that held leaders of Irish rebellions, now an OPW museum on a timed ticket. Book ahead; walk-up is unreliable. The IMMA courtyard is next door.', 53.341667, -6.309444, ST_SetSRID(ST_MakePoint(-6.309444, 53.341667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('spike-island', 'Spike Island', 'Cork', 'IE', 'Cobh', 'https://www.spikeislandcork.ie', 'A fortified island in Cork Harbour, a fortress and later a prison, reached by ferry from Cobh. Allow a half day; the island is walked, not driven.', 51.835, -8.285, ST_SetSRID(ST_MakePoint(-8.285, 51.835), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('fastnet-lighthouse', 'Fastnet Lighthouse', 'Cork', 'IE', 'Cape Clear', 'https://irishlights.ie/tourism/our-lighthouses/fastnet.aspx', 'Ireland''s most famous rock lighthouse, on a reef south of Cape Clear. There is no public landing; you see it from the island or from a boat out of Baltimore or Schull.', 51.393278, -9.604944, ST_SetSRID(ST_MakePoint(-9.604944, 51.393278), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('connemara-national-park', 'Connemara National Park', 'Galway', 'IE', 'Letterfrack', 'http://www.connemaranationalpark.ie/', 'A national park of bog, mountain and Atlantic weather around Letterfrack. The visitor centre and Diamond Hill trail are the usual start; the Twelve Bens fill the skyline.', 53.551111, -9.944722, ST_SetSRID(ST_MakePoint(-9.944722, 53.551111), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('killarney-national-park', 'Killarney National Park', 'Kerry', 'IE', 'Killarney', 'https://www.killarneynationalpark.ie/', 'Ireland''s oldest national park: three lakes, native oak, and the edge of the Reeks. Muckross, Ross Castle and Torc are inside the boundary; Killarney town sits at the gate.', 52.02099, -9.50664, ST_SetSRID(ST_MakePoint(-9.50664, 52.02099), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('burren-national-park', 'Burren National Park', 'Clare', 'IE', 'Corofin', 'https://www.nationalparks.ie/burren/', 'A national park of limestone pavement, turloughs and hazel scrub in the south-east Burren. Trails leave from Gortlecka and Mullaghmore; the visitor information is in Corofin.', 53.01, -9.0, ST_SetSRID(ST_MakePoint(-9.0, 53.01), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('wicklow-mountains-national-park', 'Wicklow Mountains National Park', 'Wicklow', 'IE', 'Glendalough', 'http://www.wicklowmountainsnationalpark.ie/', 'An upland national park of granite, bog and glacial valleys. Glendalough is the usual trailhead; the Military Road crosses the interior.', 53.018, -6.398, ST_SetSRID(ST_MakePoint(-6.398, 53.018), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('glenveagh-national-park', 'Glenveagh National Park', 'Donegal', 'IE', 'Churchill', 'http://www.glenveaghnationalpark.ie/wildlife.html', 'Donegal''s largest national park: a lake, a castle, and a herd of red deer in a glaciated valley. The visitor centre is the orientation; the rest is walking.', 55.016667, -8.05, ST_SetSRID(ST_MakePoint(-8.05, 55.016667), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('gobbins', 'The Gobbins', 'Antrim', 'NI', 'Islandmagee', 'http://thegobbinscliffpath.com', 'A cliff path of bridges and tunnels on Islandmagee, reopened as a guided walk. It is booked, not a casual stroll; weather and swell close it.', 54.801, -5.69, ST_SetSRID(ST_MakePoint(-5.69, 54.801), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('titanic-belfast', 'Titanic Belfast', 'Antrim', 'NI', 'Belfast', 'http://www.titanicbelfast.com/', 'A museum on the slipways where Titanic was built, in a building shaped like hulls. The dry dock and SS Nomadic sit on the same quay.', 54.6083, -5.90975, ST_SetSRID(ST_MakePoint(-5.90975, 54.6083), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('mount-stewart', 'Mount Stewart', 'Down', 'NI', 'Newtownards', 'https://www.nationaltrust.org.uk/mount-stewart', 'A National Trust house and garden on Strangford Lough, the gardens the equal of any in Ireland. The lough shore is part of the walk.', 54.555, -5.608, ST_SetSRID(ST_MakePoint(-5.608, 54.555), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('slieve-gullion', 'Slieve Gullion', 'Armagh', 'NI', 'Newry', 'https://www.ringofgullion.org', 'A ring-dyke mountain south of Newry with a passage tomb on the summit and a forest drive around the lower slopes. The Ring of Gullion is the wider landscape.', 54.133333, -6.433333, ST_SetSRID(ST_MakePoint(-6.433333, 54.133333), 4326)::geography);
insert into place (id, name, county, country, town, website, description, lat, lng, geom) values ('devenish-island', 'Devenish Island', 'Fermanagh', 'NI', 'Enniskillen', 'https://discovernorthernireland.com/things-to-do/devenish-island-monastic-site-p675511', 'A monastic island in Lower Lough Erne with a round tower, reached by ferry from Trory in season. The tower is among the finest in Ulster.', 54.372308, -7.657642, ST_SetSRID(ST_MakePoint(-7.657642, 54.372308), 4326)::geography);
